// INDI+P v24 — mobile account entry, Google sign-in, and community polish.
(() => {
  const V24 = window.INDIP_V24 = window.INDIP_V24 || {};
  V24.version = '24.0.0';

  const $ = (s,p=document) => p.querySelector(s);
  const v21 = () => window.INDIP_V21 || null;

  function setAuthMessage(text, ok=false){
    const el = $('#v21AuthMessage');
    if(!el) return;
    el.textContent = text;
    el.classList.toggle('ok', !!ok);
  }

  function authErrorMessage(error){
    const code = error?.code || '';
    if(code.includes('operation-not-allowed')) return 'Google 로그인을 Firebase Authentication에서 활성화해야 합니다.';
    if(code.includes('unauthorized-domain')) return '현재 사이트 도메인(indip.web.app)을 Firebase Authentication 승인 도메인에 추가해야 합니다.';
    if(code.includes('popup-blocked')) return '로그인 창이 차단되었습니다. 브라우저의 팝업 허용 후 다시 시도해주세요.';
    if(code.includes('account-exists-with-different-credential')) return '같은 이메일로 다른 로그인 방식이 이미 연결되어 있습니다.';
    return error?.message || 'Google 로그인 중 오류가 발생했습니다.';
  }

  async function googleSignInV24(){
    const v = v21();
    if(!v?.firebase) return setAuthMessage('Firebase 연결을 확인 중입니다.');
    const {auth,authmod} = v.firebase;
    const provider = new authmod.GoogleAuthProvider();
    provider.setCustomParameters({prompt:'select_account'});
    setAuthMessage('Google 로그인 창을 여는 중입니다.');
    try{
      await authmod.signInWithPopup(auth, provider);
      setAuthMessage('Google 로그인되었습니다.', true);
    }catch(error){
      const code = error?.code || '';
      if(code.includes('popup-blocked') || code.includes('operation-not-supported-in-this-environment')){
        try{
          await authmod.signInWithRedirect(auth, provider);
          return;
        }catch(redirectError){
          return setAuthMessage(authErrorMessage(redirectError));
        }
      }
      setAuthMessage(authErrorMessage(error));
    }
  }

  function enhanceAuthPanel(){
    const panel = $('#communityAuthPanelV21');
    const signedOut = $('#v21AuthSignedOut', panel || document);
    if(!panel || !signedOut || $('#v24GoogleLogin', panel)) return;

    const intro = $('.v21-auth-sheet > p', panel);
    if(intro) intro.textContent = 'Google·이메일·게스트 로그인으로 커뮤니티 글쓰기·댓글·좋아요를 여러 기기에서 이어갈 수 있습니다.';

    const social = document.createElement('div');
    social.className = 'v24-social-login';
    social.innerHTML = '<button type="button" class="v24-google-btn" id="v24GoogleLogin"><span>G</span> Google로 계속하기</button><small>카카오·네이버는 별도 OAuth 설정 후 추가할 수 있습니다.</small>';
    signedOut.insertAdjacentElement('afterbegin', social);
    $('#v24GoogleLogin', panel).onclick = googleSignInV24;
  }

  function syncMobileAccount(){
    const btn = $('.mobile-nav [data-scroll="my"]');
    if(!btn) return;
    const signedIn = !!v21()?.user;
    const label = signedIn ? 'MY' : '로그인';
    const icon = signedIn ? '◎' : '●';
    if(btn.dataset.v24Label !== label){
      btn.dataset.v24Label = label;
      btn.innerHTML = '<span>'+icon+'</span>'+label;
    }
    if(btn.dataset.v24Bound !== '1'){
      btn.dataset.v24Bound = '1';
      btn.addEventListener('click', e => {
        if(v21()?.user) return;
        e.preventDefault();
        e.stopImmediatePropagation();
        window.openCommunityAuthV21?.();
        requestAnimationFrame(enhanceAuthPanel);
      }, true);
    }
  }

  function syncCommunityCTA(){
    const quick = $('#v20CommunityQuick');
    if(!quick || $('#v24CommunityLogin', quick)) return;
    const b = document.createElement('button');
    b.id = 'v24CommunityLogin';
    b.className = 'primary v24-community-login';
    b.textContent = v21()?.user ? '내 커뮤니티' : '로그인하고 참여';
    b.onclick = () => {
      if(v21()?.user){
        $('#communityBoard')?.scrollIntoView({behavior:'smooth',block:'start'});
      }else{
        window.openCommunityAuthV21?.();
        requestAnimationFrame(enhanceAuthPanel);
      }
    };
    quick.prepend(b);
  }

  function refresh(){
    enhanceAuthPanel();
    syncMobileAccount();
    syncCommunityCTA();
    const login = $('#v24CommunityLogin');
    if(login) login.textContent = v21()?.user ? '내 커뮤니티' : '로그인하고 참여';
  }

  function boot(){
    const mo = new MutationObserver(() => requestAnimationFrame(refresh));
    mo.observe(document.body,{childList:true,subtree:true,characterData:true});
    refresh();
    setTimeout(refresh,500);
    setTimeout(refresh,1500);
    setInterval(syncMobileAccount,1500);

    const v = v21();
    if(v?.firebase?.authmod?.getRedirectResult){
      v.firebase.authmod.getRedirectResult(v.firebase.auth).catch(error => setAuthMessage(authErrorMessage(error)));
    }
  }

  if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded',boot,{once:true});
  else boot();
})();

/* INDI+P v24 — mobile typography, alignment, auth, and community fixes */
.v24-social-login{display:grid;gap:8px;margin:0 0 16px;padding:0 0 16px;border-bottom:1px solid #353b43}
.v24-google-btn{min-height:48px;width:100%;display:flex;align-items:center;justify-content:center;gap:10px;border:1px solid #d8dde4;border-radius:12px;background:#fff;color:#17191d;font-weight:850}
.v24-google-btn span{display:grid;place-items:center;width:24px;height:24px;border-radius:50%;border:1px solid #d6d9de;font-weight:900}
.v24-social-login small{color:#7f8892;line-height:1.45}
.v24-community-login{order:-1}

@media(max-width:760px){
  html,body{max-width:100%;overflow-x:hidden}
  body{font-size:14px}
  .wrap{width:calc(100% - 24px)!important;max-width:none!important}
  .topbar .nav{min-height:60px;height:auto!important;display:grid!important;grid-template-columns:minmax(0,1fr) auto;gap:8px!important;padding:8px 0}
  .brand{min-width:0;max-width:100%;gap:8px!important;overflow:hidden}
  .brand .mark{flex:0 0 36px;min-width:36px!important;width:36px!important;height:36px!important}
  #brandName{display:block;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:14px;line-height:1.1;letter-spacing:-.02em}
  #brandOrigin{display:block!important;max-width:54vw;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:7px!important;letter-spacing:.06em!important;margin-top:3px}
  .mobile-search{justify-self:end;margin-left:0!important;min-width:52px;min-height:38px;padding:7px 10px!important}
  .nav-actions{display:none!important}

  .section{padding-top:38px!important;padding-bottom:38px!important}
  .section-head{display:grid!important;grid-template-columns:1fr;gap:8px!important;margin-bottom:18px!important}
  .section-head h2,.v20-community-hero h2,.community-toolbar h3,.news-card h3,.poster-copy h3,.sheet h2{word-break:keep-all;overflow-wrap:anywhere}
  .section-head h2{font-size:clamp(28px,9vw,38px)!important;line-height:1.04!important;margin:4px 0 5px!important}
  .section-head p,.v20-community-hero p{font-size:13px!important;line-height:1.6!important;max-width:100%!important}
  .section-head>a,.section-head>button{justify-self:start;margin-top:2px!important}

  .v20-community-hub{padding-top:38px!important;padding-bottom:42px!important}
  .v20-community-hero{display:grid!important;grid-template-columns:1fr!important;gap:14px!important;align-items:start!important;padding-bottom:16px!important}
  .v20-community-hero h2{font-size:clamp(30px,9vw,42px)!important;line-height:1.04!important;margin:7px 0 9px!important}
  .v20-community-stats{display:grid!important;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px!important;width:100%}
  .v20-community-stats span{min-width:0!important;padding:9px!important;text-align:center}
  .v20-community-stats b{font-size:20px!important}
  .v20-community-quick{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px!important;margin:12px 0 16px!important}
  .v20-community-quick button{width:100%;min-width:0!important;white-space:normal;line-height:1.2}
  .v24-community-login{grid-column:1/-1}
  .v20-community-hub .community-toolbar{display:grid!important;grid-template-columns:1fr;gap:10px!important;align-items:start!important}
  .v20-community-hub .community-toolbar h3{font-size:26px!important;line-height:1.08!important}
  .board-filter{display:flex!important;flex-wrap:nowrap!important;overflow-x:auto;gap:6px!important;padding:8px 0!important;position:static!important;scrollbar-width:none}
  .board-filter::-webkit-scrollbar{display:none}
  .board-filter button{flex:0 0 auto;white-space:nowrap}
  .v20-community-hub .community-board{grid-template-columns:1fr!important;gap:10px!important}
  .v21-board-post{min-height:0!important;padding:15px!important}
  .board-author,.board-actions{align-items:flex-start}
  .board-actions{display:grid!important;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px!important}
  .board-actions button{min-width:0!important;width:100%;padding:8px 5px!important;white-space:normal}

  .v21-auth-sheet,.v21-comments-sheet,.v22-notice-sheet,.v22-report-sheet,.v22-discussion-sheet{width:100%!important;max-width:none!important;max-height:92dvh;overflow:auto;padding:20px 14px calc(20px + env(safe-area-inset-bottom))!important}
  .v21-auth-sheet h2{font-size:28px!important;line-height:1.1;margin-right:40px}
  .v21-auth-sheet>p{font-size:13px;line-height:1.55}
  .v21-auth-sheet label{margin:10px 0!important}
  .v21-auth-actions{display:grid!important;grid-template-columns:1fr 1fr;gap:7px!important}
  .v21-auth-actions button{width:100%;min-width:0;padding:0 8px!important;white-space:normal;line-height:1.15}
  .v21-comment-compose{grid-template-columns:1fr!important}
  .v21-comment-compose button{width:100%}
  .v22-social-stats{grid-template-columns:1fr 1fr!important}

  .news-card h3{font-size:clamp(22px,7vw,29px)!important;line-height:1.18!important}
  .news-card p,.poster-copy p,.board-post>p{word-break:keep-all;overflow-wrap:anywhere}
  .poster-copy{min-width:0}
  .poster-copy h3{font-size:18px!important;line-height:1.18!important}

  .mobile-nav{display:grid!important;grid-template-columns:repeat(6,minmax(0,1fr));left:0!important;right:0!important;bottom:0!important;padding:6px 2px calc(6px + env(safe-area-inset-bottom))!important;gap:0!important;overflow:hidden}
  .mobile-nav button{min-width:0!important;width:100%;padding:3px 1px!important;font-size:9px!important;line-height:1.1!important;white-space:nowrap}
  .mobile-nav button span{font-size:16px!important;line-height:1;margin-bottom:3px!important}
  .mobile-nav button[data-v24-label="로그인"]{color:#d8553f!important;font-weight:850}

  .share-sheet,.sheet{max-width:100vw!important;overflow-x:hidden}
  input,textarea,select,button{max-width:100%}
}

@media(max-width:390px){
  .wrap{width:calc(100% - 20px)!important}
  #brandOrigin{max-width:48vw}
  .v20-community-stats span{font-size:9px}
  .v20-community-quick{grid-template-columns:1fr 1fr}
  .v21-auth-actions{grid-template-columns:1fr}
  .mobile-nav button{font-size:8px!important}
  .mobile-nav button span{font-size:15px!important}
}
